/* Auto-hidden controls */
input, select, button, textarea, label, fieldset,
.dg, .lil-gui, .qs_main, .opc-container, .opc-gui, .quicksettings, .p5DomElement {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
    position: absolute !important;
    left: -9999px !important;
    top: -9999px !important;
    width: 0px !important;
    height: 0px !important;
}

code:
/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): Lawa - "Processing 音乐可视化 - Drum&Bass"
 * 原始作品討論 (Original Note): http://xhslink.com/o/85VnqTYI4bH
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。演算法靈感取材自 Lawa 創作之「Drum&Bass
 * 高 BPM 碎拍極速幾何雷達與電音雷射射線」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let NUM_RAYS = 32;
let NUM_VORTEX_PARTICLES = 250;
let radarAngle = 0;
let vortexParticles = [];
let lasers = [];

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  ellipseMode(CENTER);

  // 初始化電音渦流粒子
  for (let i = 0; i < NUM_VORTEX_PARTICLES; i++) {
    let r = random(80, 550);
    let a = random(TWO_PI);
    vortexParticles.push({
      r: r,
      a: a,
      speed: random(0.01, 0.035),
      size: random(2.0, 5.0),
      hueOffset: random(-30, 30)
    });
  }
};

draw = () => {
  // 1. 動態音訊信號平滑處理 (高敏捷度反應極速 Drum&Bass 碎拍)
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.9 : 0.25));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.95 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.18;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.35;
  smoothedMid += (rawMid - smoothedMid) * 0.22;

  radarAngle += 0.02 + smoothedMid * 0.06;

  // 2. 電音尾蹟沖刷背景
  background(260, 55, 4, 0.22);

  let cx = width * 0.5;
  let cy = height * 0.5;
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 310;

  // 3. 極速碎拍觸發「高頻碎拍雷射發射 (Snare Laser Burst)」
  if (smoothedPercussive > 0.65 && random() < 0.35) {
    let burstCount = 12;
    for (let b = 0; b < burstCount; b++) {
      let lAngle = (TWO_PI / burstCount) * b + radarAngle;
      lasers.push({
        r: 60.0,
        maxR: max(width, height) * 0.85,
        angle: lAngle,
        speed: random(25.0, 45.0),
        hue: (currentHue + random(-20, 40)) % 360,
        weight: random(2.0, 5.0)
      });
    }
  }

  // 4. 更新與渲染極速雷射束 (Lasers Update Loop)
  for (let i = lasers.length - 1; i >= 0; i--) {
    let l = lasers[i];
    l.r += l.speed * (1.0 + smoothedSubBass * 0.6);

    if (l.r > l.maxR) {
      lasers.splice(i, 1);
      continue;
    }

    let alpha = map(l.r, 60, l.maxR, 0.95, 0.0);
    let x1 = cx + (l.r - 40) * cos(l.angle);
    let y1 = cy + (l.r - 40) * sin(l.angle);
    let x2 = cx + l.r * cos(l.angle);
    let y2 = cy + l.r * sin(l.angle);

    stroke(l.hue, 85, 100, alpha);
    strokeWeight(l.weight * (1.0 + smoothedPercussive));
    line(x1, y1, x2, y2);
  }

  // 5. 渲染極速中心幾何雷達與頻譜環 (Geometric Radar & Spectrum Rings)
  noFill();

  // (A) 雷達輻射線條
  for (let i = 0; i < NUM_RAYS; i++) {
    let a = (TWO_PI / NUM_RAYS) * i + radarAngle;
    let rLength = 160 + sin(a * 4 + radarAngle * 2) * 40 + smoothedSubBass * 180;
    let rx = cx + rLength * cos(a);
    let ry = cy + rLength * sin(a);

    let rayAlpha = (i % 2 === 0 ? 0.75 : 0.35);
    stroke((currentHue + i * 8) % 360, 85, 95, rayAlpha);
    strokeWeight(1.2 + smoothedSubBass * 2.0);
    line(cx, cy, rx, ry);
  }

  // (B) 幾何頻譜脈衝環
  strokeWeight(2.0 + smoothedPercussive * 4.0);
  for (let r = 1; r <= 4; r++) {
    let ringRadius = r * 80 * (1.0 + smoothedSubBass * 0.35);
    stroke((currentHue + r * 30) % 360, 80, 95, 0.65);
    ellipse(cx, cy, ringRadius * 2.0, ringRadius * 2.0);
  }

  // 6. 渲染外圍渦流粒子場 (Outer Vortex Field)
  noStroke();
  for (let i = 0; i < vortexParticles.length; i++) {
    let vp = vortexParticles[i];
    vp.a += vp.speed * (1.0 + smoothedMid * 1.5);

    let dynR = vp.r * (1.0 + sin(radarAngle * 2 + i) * 0.15 + smoothedSubBass * 0.3);
    let px = cx + dynR * cos(vp.a);
    let py = cy + dynR * sin(vp.a);

    let vpHue = (currentHue + vp.hueOffset) % 360;
    fill(vpHue, 85, 100, 0.85);
    ellipse(px, py, vp.size * (1.0 + smoothedPercussive * 1.2), vp.size * (1.0 + smoothedPercussive * 1.2));
  }

  // 7. 中心 Drum&Bass 電音重低頻心臟 (Bass Core)
  let coreSize = (40.0 + smoothedSubBass * 80.0 + smoothedPercussive * 30.0);
  fill((currentHue + 50) % 360, 90, 100, 0.95);
  ellipse(cx, cy, coreSize, coreSize);
};

// === 運行時防崩潰護欄與 DOM 代理 Stubs ===
if (typeof createP === 'undefined') window.createP = function() { return { position: function(){}, style: function(){} }; };
if (typeof createDiv === 'undefined') window.createDiv = function() { return { position: function(){}, style: function(){} }; };
if (typeof createButton === 'undefined') window.createButton = function() { return { position: function(){}, style: function(){} }; };
if (typeof createSlider === 'undefined') window.createSlider = function() { return { position: function(){}, style: function(){} }; };
